r"""Render an existing Unstructured Transform JSON locally; no API or OCR calls.

Usage (inside conda venv):
    python .\review\render_unstructured.py .\transform-result-....json
All source rows, including headers and totals, are retained for inspection.
This is an extraction preview, not a shortage-matching or ordering program.
"""

import argparse
import html
from html.parser import HTMLParser
import json
from pathlib import Path
import re
import sys


class TableReader(HTMLParser):
    """Read cell text and spans without executing or rendering source HTML."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.tables = []
        self.table = self.row = self.cell = None
        self.fragments = []

    def handle_starttag(self, tag, attrs):
        if tag == "table":
            if self.table is not None:
                raise ValueError("Nested tables need a separate review.")
            self.table = []
        elif tag == "tr" and self.table is not None:
            if self.row is not None:
                raise ValueError("An unclosed table row was found.")
            self.row = []
        elif tag in ("td", "th") and self.row is not None:
            if self.cell is not None:
                raise ValueError("An unclosed table cell was found.")
            attrs = dict(attrs)
            self.cell = {"text": "", "header": tag == "th"}
            for attribute in ("rowspan", "colspan"):
                value = int(attrs.get(attribute, "1"))
                if not 1 <= value <= 1000:
                    raise ValueError("An unsupported cell span was found.")
                self.cell[attribute] = value
            self.fragments = []
        elif tag == "br" and self.cell is not None:
            self.fragments.append("\n")

    def handle_data(self, data):
        if self.cell is not None:
            self.fragments.append(data)

    def handle_endtag(self, tag):
        if tag in ("td", "th") and self.cell is not None:
            self.cell["text"] = "".join(self.fragments)
            self.row.append(self.cell)
            self.cell = None
        elif tag == "tr" and self.row is not None:
            if self.cell is not None:
                raise ValueError("A row ended before its cell was closed.")
            self.table.append(self.row)
            self.row = None
        elif tag == "table" and self.table is not None:
            if self.row is not None:
                raise ValueError("A table ended before its row was closed.")
            self.tables.append(self.table)
            self.table = None


def read_tables(markup):
    parser = TableReader()
    parser.feed(markup)
    parser.close()
    if parser.table is not None or parser.row is not None or parser.cell is not None:
        raise ValueError("Incomplete table HTML; source JSON has not been changed.")
    if not parser.tables:
        raise ValueError("No HTML table was found.")
    return parser.tables


def render_table(rows):
    parts = ['<div class="table-wrap"><table dir="rtl">']
    for row in rows:
        parts.append("<tr>")
        for cell in row:
            tag = "th" if cell["header"] else "td"
            numeric = bool(re.fullmatch(r"[\d.,+%:/\s-]+", cell["text"]))
            direction = "ltr" if numeric else "auto"
            parts.append(
                f'<{tag} rowspan="{cell["rowspan"]}" colspan="{cell["colspan"]}" '
                f'dir="{direction}">{html.escape(cell["text"])}</{tag}>'
            )
        parts.append("</tr>")
    parts.append("</table></div>")
    return "".join(parts)


def prepare_preview(data):
    if not isinstance(data, dict) or not isinstance(data.get("elements"), list):
        raise ValueError("Expected a complete Transform JSON response with an elements list.")
    if data.get("status") != "completed":
        raise ValueError("This response is not marked completed; inspect its status first.")
    if not data["elements"]:
        raise ValueError("The elements list is empty; a Markdown-only export is insufficient.")
    labels = {"Image": "نص الصورة", "NarrativeText": "نص", "Title": "عنوان",
              "Header": "رأس الصفحة", "Form": "بيانات المستند",
              "Table": "عنصر مصنّف كجدول", "Footer": "تذييل الصفحة"}
    cards, exported_tables, issues = [], [], []
    for index, element in enumerate(data["elements"]):
        kind = element.get("type", "Unknown")
        metadata = element.get("metadata") or {}
        markup = metadata.get("text_as_html")
        issue_context = {"element_index": index, "element_id": element.get("element_id"),
                         "page_number": metadata.get("page_number"), "element_type": kind}
        content = '<pre dir="auto">' + html.escape(element.get("text") or "") + '</pre>'
        if markup:
            try:
                tables = read_tables(markup)
                content = "".join(render_table(rows) for rows in tables)
                exported_tables.append({
                    "element_id": element.get("element_id"), "element_type": kind,
                    "page_number": metadata.get("page_number"), "tables": tables,
                })
            except (TypeError, ValueError) as error:
                issues.append({**issue_context, "error": str(error),
                               "source_text": element.get("text") or ""})
                content = '<p class="warning">تعذّر عرض بنية الجدول؛ النص أدناه للمراجعة فقط.</p>' + content
        elif kind == "Table":
            issues.append({**issue_context, "error": "Table has no text_as_html.",
                           "source_text": element.get("text") or ""})
            content = '<p class="warning">هذا الجدول موجود كنص فقط؛ لا نفترض حدود صفوفه.</p>' + content
        title = html.escape(labels.get(kind, kind))
        page = html.escape(str(metadata.get("page_number", "—")))
        cards.append(f'<section><h2>{title} <small>— صفحة {page}</small></h2>{content}</section>')
    source_name = (data.get("source") or {}).get("filename", "غير محدد")
    warnings = data.get("warnings", [])
    warnings_text = json.dumps(warnings, ensure_ascii=False) if warnings else "لا توجد تحذيرات في الرد"
    document = '''<!doctype html>
<html lang="ar" dir="rtl"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'">
<title>مراجعة نتيجة Unstructured</title><style>
body{font-family:Tahoma,Arial,sans-serif;background:#f3f6fa;color:#182636;margin:0;padding:28px}
main{max-width:1200px;margin:auto}h1{font-size:26px}h2{font-size:19px}
section,.intro{background:#fff;border:1px solid #d5dfeb;border-radius:10px;padding:20px;margin:18px 0}
p{line-height:1.9}small{font-weight:normal;color:#526478}.table-wrap{overflow-x:auto}
table{border-collapse:collapse;width:100%}th,td{padding:11px;border:1px solid #cdd8e5;text-align:start;white-space:pre-wrap}
th{background:#e8f0fa}tr:nth-child(even){background:#f7faff}td[dir=ltr]{text-align:center}
pre{white-space:pre-wrap;unicode-bidi:plaintext;font:16px/1.9 Tahoma,Arial,sans-serif}
.warning{background:#fff1dc;padding:12px}code{direction:ltr;unicode-bidi:isolate}
</style></head><body><main><h1>مراجعة نتيجة Unstructured</h1><div class="intro">
<p>معاينة محلية من ملف JSON الموجود، من غير OCR أو اتصال بالـAPI.</p>
<p>النص والأرقام محفوظان كما وردا. لم نصحح أسماء الأصناف، ولم نستنتج أرقامًا ناقصة.
تظهر أعمدة المصدر وصفوف العناوين والإجماليات للمراجعة؛ هذه ليست قائمة طلبات الشراء.</p>'''
    document += '<p>المصدر: <bdi>' + html.escape(str(source_name)) + '</bdi></p>'
    document += '<p>عدد صفحات الرد: ' + html.escape(str((data.get("metadata") or {}).get("page_count", "—"))) + '</p>'
    document += '<p>معرّف النتيجة: <bdi>' + html.escape(str(data.get("id", "—"))) + '</bdi></p>'
    document += '<p>إعداد الجودة: <bdi>' + html.escape(str(data.get("profile", "—"))) + '</bdi></p>'
    document += '<p>' + html.escape(warnings_text) + '؛ غياب التحذيرات لا يضمن دقة القراءة.</p>'
    if issues:
        document += (
            '<p class="warning"><strong>الاستخراج محفوظ والمعاينة متاحة، لكن بنية الجداول تحتاج مراجعة.</strong><br>'
            'عدد العناصر التي تعذّر الحصول على خلاياها: ' + str(len(issues)) + '. '
            'النص أدناه من الرد الأصلي؛ لم نخمّن حدود الصفوف أو نربط الأرقام بالأصناف. '
            'تصنيف العنصر كجدول لا يعني أنه جدول أدوية؛ قد يشمل عنوانًا أو تذييلًا.</p>'
        )
    document += '</div>'
    document += "".join(cards) + '</main></body></html>'
    return document, {"result_id": data.get("id"), "source": data.get("source"),
                      "note": "Available HTML table cells retain headers, totals and spans. Unstructured text is retained in preview_issues; no missing row boundaries are inferred. No medicine matching.",
                      "preview_status": "needs_review" if issues else "structured",
                      "tables": exported_tables, "preview_issues": issues}


def main():
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("input", type=Path, help="Existing Transform result JSON")
    args = parser.parse_args()
    source = args.input.resolve()
    data = json.loads(source.read_text(encoding="utf-8-sig"))
    document, tables = prepare_preview(data)
    output_dir = Path(__file__).resolve().parent / "unstructured_preview" / source.stem
    output_dir.mkdir(parents=True, exist_ok=True)
    (output_dir / "preview.html").write_text(document, encoding="utf-8")
    (output_dir / "tables.json").write_text(json.dumps(tables, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"Preview: {output_dir / 'preview.html'}")
    print(f"Table cells: {output_dir / 'tables.json'}")
    if tables["preview_issues"]:
        print("Some tables need review. See preview_issues in tables.json.")
        raise SystemExit(2)
    print("DONE. This checks the saved structure, not OCR accuracy.")


if __name__ == "__main__":
    main()

