    {"id": "row_11", "row": 11, "label": "لوفير", "reference_numbers": ["400", "45"]},
)


def line_centers(mask):
    """Return the centers of contiguous dark grid-line positions."""
    centers = []
    start = None
    for index, is_line in enumerate(list(mask) + [False]):
        if is_line and start is None:
            start = index
        elif not is_line and start is not None:
            centers.append((start + index - 1) // 2)
            start = None
    return centers


def merge_nearby_lines(centers, max_span):
    """Treat the two strokes of a double border as one cell boundary."""
    groups = []
    for center in centers:
        if groups and center - groups[-1][0] <= max_span:
            groups[-1].append(center)
        else:
            groups.append([center])
    return [(group[0] + group[-1]) // 2 for group in groups]


