        if not weight.is_file() or weight.stat().st_size == 0:
            raise FileNotFoundError(f"Local model is missing; no download attempted: {weight}")

    # Set before importing MinerU: its configuration path is read at import time.
    os.environ["MINERU_MODEL_SOURCE"] = "local"
    os.environ["MINERU_TOOLS_CONFIG_JSON"] = str(CONFIG)
    os.environ["HF_HUB_OFFLINE"] = "1"
    os.environ["TRANSFORMERS_OFFLINE"] = "1"

    import numpy as np
    from PIL import Image

    with Image.open(TABLE_IMAGE) as source:
        table = source.convert("RGB")
    gray = np.asarray(table.convert("L"))
    height, width = gray.shape
    raw_row_lines = line_centers((gray[:, int(width * .02):int(width * .98)] < 180).mean(axis=1) > .70)
    col_lines = line_centers((gray[int(height * .02):int(height * .98), :] < 180).mean(axis=0) > .80)
    # This saved table has a header plus 19 products, and six columns.
    # The header's bottom border has two strokes. Merge only nearby strokes,
    # within 15% of one expected row height; do not remove an arbitrary line.
    row_lines = merge_nearby_lines(raw_row_lines, max_span=max(2, round(height / 20 * .15)))
    if len(row_lines) != 21 or len(col_lines) != 7:
        raise RuntimeError(
            f"Grid check failed: found {len(row_lines)} horizontal and {len(col_lines)} vertical "
            f"boundaries after merging nearby strokes (raw horizontal: {raw_row_lines}); "
            "expected 21 and 7. Stopped before OCR to avoid reading the wrong cells."
        )
    row_heights = np.diff(row_lines)
    typical_height = float(np.median(row_heights))
    if np.any(row_heights < typical_height * .75) or np.any(row_heights > typical_height * 1.25):
        raise RuntimeError(
            f"Grid spacing check failed: row heights are {row_heights.tolist()}. "
            "Stopped before OCR to avoid reading the wrong cells."
        )
    print(
        f"Grid: {len(raw_row_lines)} horizontal strokes -> {len(row_lines)} boundaries, "
        f"{len(col_lines)} vertical boundaries.", flush=True
    )

