r"""User-run Unstructured Transform API trial: best quality, elements output.

    python .\review\parse_unstructured_api.py ".\جملة العمروووو.pdf"
    python .\review\parse_unstructured_api.py --from-json .\saved-result.json

Uploads the selected PDF to Unstructured. Reads the API key from the environment
or a hidden local prompt. Does not install packages or run local OCR models.
Each normal invocation starts a new extraction; --resume only polls an existing job.
The full response is kept before attempting to render its tables.
--from-json rebuilds only local previews: no API key, upload, or network call.
"""

import argparse
from datetime import datetime
import getpass
import hashlib
import json
import os
from pathlib import Path
import sys
import time
from urllib.parse import urljoin, urlsplit

from render_unstructured import prepare_preview


BASE_URL = "https://transform.unstructured.io"
PARSE_URL = BASE_URL + "/api/v2/parse"
OUTPUT_ROOT = Path(__file__).resolve().parent / "unstructured_api"


def write_json(path, data):
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")


def checked_poll_url(value, base=PARSE_URL):
    url = urljoin(base, value)
    parsed = urlsplit(url)
    if (parsed.scheme != "https" or parsed.hostname != "transform.unstructured.io"
            or parsed.port not in (None, 443) or parsed.username or parsed.password
            or not parsed.path.startswith("/api/")):
        raise ValueError("Unexpected job URL. Stopped before sending the API key to it.")
    return url


def completed_result(payload):
    """Accept the direct Parse result, or the result inside a completed job."""
    if payload.get("status") != "completed":
        return None
    if isinstance(payload.get("elements"), list):
        return payload
    result = payload.get("result")
    if isinstance(result, dict) and isinstance(result.get("elements"), list):
        return {"status": "completed", **result}
    raise ValueError("Job completed, but its result format needs inspection. The response is saved.")


def collect_response(session, response, run_dir, api_key, poll_url=None):
    deadline = time.monotonic() + 1800
    while True:
        # Never save request headers or the API key, including in an error response.
        raw = response.content.replace(api_key.encode("utf-8"), b"[API_KEY_REDACTED]")
        (run_dir / "response.json").write_bytes(raw)
        if response.status_code not in (200, 201, 202):
            raise RuntimeError(f"Unstructured returned HTTP {response.status_code}. See response.json.")
        payload = json.loads(raw.decode("utf-8-sig"))
        if not isinstance(payload, dict):
            raise ValueError("Unexpected response format; see the saved response.json.")
        location = response.headers.get("Location")
        if location:
            poll_url = checked_poll_url(location, response.url)
        state = {"poll_url": poll_url, "id": payload.get("id"), "status": payload.get("status")}
        write_json(run_dir / "job.json", state)
        if payload.get("status") in ("failed", "cancelled", "canceled"):
            raise RuntimeError("Unstructured reported a failed or cancelled job. See response.json.")
        result = completed_result(payload)
        if result is not None:
            return result
        pending = response.status_code == 202 or payload.get("status") in (
            "pending", "queued", "running", "processing", "in_progress"
        )
        if not pending:
            raise ValueError("Unrecognized response status; see response.json before retrying.")
        if not poll_url:
            raise RuntimeError("Request accepted without a follow-up URL. Check this job in the website; do not resubmit yet.")
        if time.monotonic() >= deadline:
            raise TimeoutError("Still processing after 30 minutes. Use --resume to continue the same job.")
        print(f"Job status: {payload.get('status', 'pending')}. Waiting 10 seconds...", flush=True)
        time.sleep(10)
        response = session.get(poll_url, timeout=(30, 120), allow_redirects=False)


def save_preview(result, run_dir):
    """Publish a reviewable preview even when table cells are unavailable."""
    document, tables = prepare_preview(result)
    (run_dir / "preview.html").write_text(document, encoding="utf-8")
    write_json(run_dir / "tables.json", tables)
    OUTPUT_ROOT.mkdir(parents=True, exist_ok=True)
    (OUTPUT_ROOT / "latest.html").write_text(document, encoding="utf-8")
    write_json(run_dir / "preview_status.json", {
        "status": tables["preview_status"], "result_id": result.get("id"),
        "issue_count": len(tables["preview_issues"]),
        "note": "Table structure review only; OCR accuracy has not been verified.",
    })
    print(f"Preview: {run_dir / 'preview.html'}", flush=True)
    if tables["preview_issues"]:
        print(
            f"PREVIEW READY - NEEDS REVIEW: {len(tables['preview_issues'])} elements have unavailable table structure. "
            "The saved extraction was not changed. This result is not ready for row-based matching.", flush=True
        )
    else:
        print("DONE. Review the preview against the original PDF.", flush=True)
    print(f'Open it: Invoke-Item "{run_dir / "preview.html"}"', flush=True)
    if result.get("warnings"):
        print("The API returned warnings; they are preserved in result.json.", flush=True)
    return 2 if tables["preview_issues"] else 0


def save_completed_result(result, run_dir):
    write_json(run_dir / "result.json", result)
    if isinstance(result.get("markdown"), str):
        (run_dir / "result.md").write_text(result["markdown"], encoding="utf-8")
    if result.get("profile") != "best":
        raise ValueError("The saved result does not confirm profile=best. Inspect result.json before continuing.")
    print(f"Result JSON: {run_dir / 'result.json'}", flush=True)
    return save_preview(result, run_dir)


def main():
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("pdf", type=Path, nargs="?", help="PDF to send to Unstructured")
    parser.add_argument("--resume", type=Path, help="Existing job.json; polls without uploading again")
    parser.add_argument("--from-json", type=Path, help="Rebuild previews from a saved result, entirely offline")
    args = parser.parse_args()
    if sum(value is not None for value in (args.pdf, args.resume, args.from_json)) != 1:
        parser.error("Choose exactly one: a PDF, --resume job.json, or --from-json result.json.")
    if Path(sys.prefix).name.lower() != "venv":
        parser.error("Activate the main conda environment: conda activate venv")
    if args.from_json:
        source = args.from_json.resolve()
        result = json.loads(source.read_text(encoding="utf-8-sig"))
        # Keep the original JSON intact and rebuild only derived review files.
        run_dir = source.parent / (source.stem + "_preview")
        run_dir.mkdir(parents=True, exist_ok=True)
        print(f"Offline preview from: {source}", flush=True)
        print("No API call, upload, or local OCR. No account pages used.", flush=True)
        return save_preview(result, run_dir)
    import requests

    poll_url = None
    if args.resume:
        job_file = args.resume.resolve()
        job = json.loads(job_file.read_text(encoding="utf-8-sig"))
        if not job.get("poll_url"):
            raise ValueError("No saved polling URL. Inspect the job in the website first.")
        poll_url = checked_poll_url(job["poll_url"])
        run_dir = job_file.parent
    else:
        pdf = args.pdf.resolve()
        if not pdf.is_file() or pdf.suffix.lower() != ".pdf":
            parser.error("Provide an existing PDF file.")
        content = pdf.read_bytes()
        if not content.startswith(b"%PDF-"):
            parser.error("The selected file does not start with a PDF header.")
        print(f"PDF: {pdf}", flush=True)
        print("This run sends the PDF to Unstructured: profile=best, output=elements.", flush=True)
        print("A new extraction uses your account's page allowance.", flush=True)

    api_key = os.environ.get("UNSTRUCTURED_API_KEY", "").strip()
    if not api_key:
        api_key = getpass.getpass("Paste your Unstructured API key (hidden), then press Enter: ").strip()
    if not api_key:
        raise ValueError("No API key entered. Nothing was submitted.")
    if not args.resume:
        run_dir = OUTPUT_ROOT / datetime.now().strftime("run_%Y%m%d_%H%M%S_%f")
        run_dir.mkdir(parents=True, exist_ok=False)
        write_json(run_dir / "request.json", {
