    except Exception as error:
        message = str(error).replace(api_key, "[API_KEY_REDACTED]")
        (run_dir / "error.txt").write_text(message, encoding="utf-8")
        print(f"STOPPED: {message}", flush=True)
        print(f"Saved information: {run_dir}", flush=True)
