"""Compare Arabic and English OCR on three cells from the existing Amr table.

Run manually in conda venv. This is a diagnostic for this one saved table,
not a general table extractor or a medicine matching program.
"""

import base64
import html
import importlib.metadata
import json
import os
from pathlib import Path
import re
import sys
from datetime import datetime


PROJECT = Path(__file__).resolve().parents[1]
CONFIG = PROJECT / "review" / "mineru-local.json"
TABLE_IMAGE = (
    PROJECT / "review" / "mineru_local_rtl" / "جملة العمروووو" / "ocr"
    / "images" / "00f40861e592388adefb7e9e6619bbd58632e51aae5bb83f7517ce0e9742eb9e.jpg"
)
SAMPLES = (
    {"id": "row_01", "row": 1, "label": "أفيروكوكسيب", "reference_numbers": ["90", "32"]},
    {"id": "row_09", "row": 9, "label": "ستيميولان", "reference_numbers": ["400"]},
    {"id": "row_11", "row": 11, "label": "لوفير", "reference_numbers": ["400", "45"]},
)


def line_centers(mask):
    """Return the centers of contiguous dark grid-line positions."""
    centers = []
    start = None
    for index, is_line in enumerate(list(mask) + [False]):
        if is_line and start is None:
            start = index
        elif not is_line and start is not None:
            centers.append((start + index - 1) // 2)
            start = None
    return centers


def merge_nearby_lines(centers, max_span):
    """Treat the two strokes of a double border as one cell boundary."""
    groups = []
    for center in centers:
        if groups and center - groups[-1][0] <= max_span:
            groups[-1].append(center)
        else:
            groups.append([center])
    return [(group[0] + group[-1]) // 2 for group in groups]


