    )
    render_report(data, run_dir, latest_path)


def main():
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    if Path(sys.prefix).name.lower() != "venv":
        raise RuntimeError("Activate the conda environment first: conda activate venv")
    print(f"Python: {sys.executable}", flush=True)
    for path in (CONFIG, TABLE_IMAGE):
        if not path.is_file():
            raise FileNotFoundError(f"Required input is missing: {path}")

    config = json.loads(CONFIG.read_text(encoding="utf-8-sig"))
    model_dir = Path(config["models-dir"]["pipeline"]) / "models" / "OCR" / "paddleocr_torch"
    for name in (
        "ch_PP-OCRv5_det_infer.pth",
        "arabic_PP-OCRv5_rec_infer.pth",
        "en_PP-OCRv5_rec_infer.pth",
    ):
        weight = model_dir / name
        if not weight.is_file() or weight.stat().st_size == 0:
            raise FileNotFoundError(f"Local model is missing; no download attempted: {weight}")

    # Set before importing MinerU: its configuration path is read at import time.
    os.environ["MINERU_MODEL_SOURCE"] = "local"
    os.environ["MINERU_TOOLS_CONFIG_JSON"] = str(CONFIG)
    os.environ["HF_HUB_OFFLINE"] = "1"
    os.environ["TRANSFORMERS_OFFLINE"] = "1"

    import numpy as np
    from PIL import Image

    with Image.open(TABLE_IMAGE) as source:
        table = source.convert("RGB")
    gray = np.asarray(table.convert("L"))
    height, width = gray.shape
    raw_row_lines = line_centers((gray[:, int(width * .02):int(width * .98)] < 180).mean(axis=1) > .70)
    col_lines = line_centers((gray[int(height * .02):int(height * .98), :] < 180).mean(axis=0) > .80)
    # This saved table has a header plus 19 products, and six columns.
    # The header's bottom border has two strokes. Merge only nearby strokes,
    # within 15% of one expected row height; do not remove an arbitrary line.
    row_lines = merge_nearby_lines(raw_row_lines, max_span=max(2, round(height / 20 * .15)))
    if len(row_lines) != 21 or len(col_lines) != 7:
        raise RuntimeError(
            f"Grid check failed: found {len(row_lines)} horizontal and {len(col_lines)} vertical "
            f"boundaries after merging nearby strokes (raw horizontal: {raw_row_lines}); "
            "expected 21 and 7. Stopped before OCR to avoid reading the wrong cells."
        )
    row_heights = np.diff(row_lines)
    typical_height = float(np.median(row_heights))
    if np.any(row_heights < typical_height * .75) or np.any(row_heights > typical_height * 1.25):
        raise RuntimeError(
            f"Grid spacing check failed: row heights are {row_heights.tolist()}. "
            "Stopped before OCR to avoid reading the wrong cells."
        )
    print(
        f"Grid: {len(raw_row_lines)} horizontal strokes -> {len(row_lines)} boundaries, "
        f"{len(col_lines)} vertical boundaries.", flush=True
    )

    started = datetime.now().astimezone()
    output_root = PROJECT / "review" / "ocr_digits_probe"
    run_dir = output_root / started.strftime("run_%Y%m%d_%H%M%S_%f")
    run_dir.mkdir(parents=True, exist_ok=False)
    latest_path = output_root / "latest.html"
    data = {
        "started_at": started.isoformat(),
        "source_image": str(TABLE_IMAGE),
        "python": sys.executable,
        "mineru_version": importlib.metadata.version("mineru"),
        "mode": "whole-cell recognition, no text detection or table reconstruction",
        "grid": {"rows": row_lines, "columns": col_lines, "raw_rows": raw_row_lines},
        "status": "الصور جاهزة؛ القراءة لم تكتمل بعد",
        "samples": [],
    }
    crops_bgr = []
    for sample in SAMPLES:
        row = sample["row"]
        box = (col_lines[4] + 4, row_lines[row] + 4, col_lines[5] - 4, row_lines[row + 1] - 4)
        cell = table.crop(box)
        image_name = sample["id"] + ".png"
        cell.save(run_dir / image_name)
        crops_bgr.append(np.asarray(cell)[:, :, ::-1].copy())
        data["samples"].append({**sample, "box": list(box), "image": image_name, "readings": {}})
    save_results(data, run_dir, latest_path)
    print(f"Crops saved to: {run_dir}", flush=True)
    print("Loading MinerU OCR libraries...", flush=True)

    try:
        from mineru.model.ocr.pytorch_paddle import PytorchPaddleOCR

        for language in ("arabic", "en"):
            print(f"Loading local {language} model and reading the three cells...", flush=True)
            engine = PytorchPaddleOCR(lang=language, enable_merge_det_boxes=False)
            readings = engine.ocr(crops_bgr, det=False, rec=True, tqdm_enable=True)[0]
            if len(readings) != len(data["samples"]):
                raise RuntimeError(f"Unexpected number of OCR results for {language}: {len(readings)}")
            for sample, (text, score) in zip(data["samples"], readings):
                sample["readings"][language] = {
                    "text": str(text),
                    "score": float(score),
                    "number_groups": re.findall(r"\d+(?:[./]\d+)*", str(text)),
                }
                print(f"  {sample['id']} [{language}]: {text}", flush=True)
            data["status"] = f"اكتملت قراءة {language}"
            save_results(data, run_dir, latest_path)
            del engine
        data["status"] = "اكتملت القراءتان؛ قارن النتائج بالصور"
    except Exception as error:
        data["status"] = "لم تكتمل التجربة: " + str(error)
        save_results(data, run_dir, latest_path)
        raise
    save_results(data, run_dir, latest_path)
    print(f"DONE. Open this report: {latest_path}", flush=True)
    print(f"Raw results: {run_dir / 'results.json'}", flush=True)


if __name__ == "__main__":
